<template><div style="max-width:400px;margin:12vh auto" class="panel"><h1>◈ NetworkDocs</h1><p class="muted">Sign in to your infrastructure documentation.</p><form @submit.prevent="login"><div class="fields" style="grid-template-columns:1fr"><label>Email<input v-model="email" type="email" required autocomplete="username"></label><label>Password<input v-model="password" type="password" required autocomplete="current-password"></label></div><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></form></div></template><script setup lang="ts">definePageMeta({layout:false});const email=ref(''),password=ref(''),error=ref(''),busy=ref(false),auth=useAuth();async function login(){busy.value=true;error.value='';try{auth.value=await $fetch('/api/auth/login',{method:'POST',body:{email:email.value,password:password.value}});await navigateTo('/')}catch(e:any){error.value=e?.data?.statusMessage||'Sign in failed'}finally{busy.value=false}}</script>
